def main():
 candidate=OUT/'prepared_v1';proposal=json.loads((candidate/'proposal.json').read_text('utf8'));checks={n:json.loads((candidate/(n+'.verification.json')).read_text('utf8'))for n in proposal['files']};readback=sorted(candidate.glob('*.png'))
 views=['fourth_ladder_preview_v1.png','ultimate_dash_preview_v2a.png','ultimate_dash_preview_v2b.png','moving_fire_inputs/base/03_moving_fire_poses.png','primary_art_inputs/01_run_four_poses.png','primary_art_inputs/02_firing_four_poses.png','primary_art_inputs/03_idle_master.png','primary_art_inputs/04_standing_fire_master.png','primary_art_inputs/idle_cycle_reference.png']
 views += [p.relative_to(OUT).as_posix()for p in readback]
 log={'actual_view_image_readback':True,'viewed_images':[{'path':(OUT/p).relative_to(ROOT).as_posix(),'sha256':digest(OUT/p)}for p in views],'native_readback_sheets':len(readback),'coverage':'포스10참조, Ultimate18참조의 재킷/수영복을 현재 대기 옆에서 열람. 게임 실기가 아님.','source_art_also_viewed':'work/ver_rin_nana/nana_ultimate_armor/dash_hair_v1/generated.png','limits':['사다리 가는 외곽/뒤 베일의 전체 그림체는 이 피부 명암 후보로 해결되지 않는다.','대시 원화 자체에도 큰 두 톤 덩어리가 남아 대기와 완전히 같은 디테일이라고 주장하지 않는다.','이동사격과 대시 사격의 원래 팔/소매/고립점 문제는 새 그림과 등록 검토가 필요하다.']};write(OUT/'final_visual_log.json',log)
 lines=['# 나나 원화 디테일 복원 후보 인계','',f'기준 BIN: `{SOURCE.relative_to(ROOT).as_posix()}`',f'SHA-256: `{EXPECTED}`','', '별도 ARC 두 개만 준비했다. 현재 BIN·포인터·세이브·카드·에뮬레이터는 수정하지 않았다. 새 그림도 생성하지 않았다. 이 결과는 원화에서 잃어버린 일부 명암의 복원 후보이며, 사용자 요청의 전모션 스타일 통일 완료본이 아니다.','', '## 후보 범위','', '| 자원 | 선택 범위 | 수정 | SHA-256 |','| --- | --- | --- | --- |']
 for name,q in checks.items():
  label='포스 사다리 144..152,155'if name.startswith('PL00')else'Ultimate 대시 67..84, 획득 전 재킷/후 수영복'
  desc='leg8의 기존 피부 내부 인덱스만 원화 명암으로 복원'if name.startswith('PL00')else'앞/뒷머리의 분홍 소재만 같은 눈 위치·머리 높이에서 원화 직접 등록'
  lines.append(f'| {name} | {label} | {desc} | `{q["after"]}` |')
 lines += ['','`prepared_v1/proposal.json`이 통합용 계약이다. 두 자원을 따로 채택할 수 있으며 부모 SHA를 먼저 확인해야 한다. 현재 공개 포인터에는 연결하지 않았다.','', '포스는 원화 등록 뒤 행 전체를 색12로 덮던 코드 때문에 잃은 정강이 음영을 복원했다. 대표144/146/149/151에서 각각3/3/7/5픽셀이며, 반전과 사격 관계를 포함한 총10참조다. 발·검은 외곽·옷의 실루엣을 재설계하지 않았다. 원화의 살색 인덱스10..13만 같은 행의 다리 내부에 대응했다.','', 'Ultimate는 이미 축소한 뒷머리를 다시 늘리던 단계를 없애고 고해상도 원화의 영역을 최종 네이티브 격자에 직접 투표 등록했다. 앞머리까지 원화에서 함께 등록하며, 눈~귀 높이16픽셀과 기존 눈 원점·머리 끝 범위를 유지했다. 기존 비분홍 소재·투명도는 보존하고 사격 팔이 가리는 픽셀은 변경하지 않았다. 피부·의상·총을 색으로 늘려 채우거나 옛 단순 머리로 다시 덮지 않았다.','', '## 실행한 검사','']
 for name,q in checks.items():
  lines.append(f'- `{name}`: raw 참조 {q["raw_references"]}개, 레이어 {q["layers"]}개, 부분 마스크16×팔2×유효228참조 = {q["mask_arm_combinations"]}개를 대조했다. 의도된 조합 변화 {q["changed_combinations"]}개. GPU 경계 관련 파츠 {q["gpu_parts"]}개를 확인했다.')
 lines += ['- 모든 비대상 raw/표시 레이어, 조립, 팔레트, 음향, 타이밍, 타일 수, 은행 시작/끝, 레이어/합성 알파가 그대로다. 두 자원 모두32타일 이하다.','- 타일 첫 열 및 flipY 첫 행은 기존 값과 동일하다.','- 동일 입력 재구성 두 ARC의 바이트 동일, 잘못된 부모/자원/등록표/대상 그림/소스 레시피 등7개 입력 거부를 확인했다. `prepared_v1/reproduction.json`.','- 8개 readback PNG를 실제 열람했다. 명시된 시각 검토 범위는 `final_visual_log.json`. 게임 로딩 및 연속동작 실기는 미실행이다.','', '## 다음 미술 제작','', '`primary_art_inputs/`의 네 장은 새 그림 순서가 왔을 때 사용할 원점 보존 입력이다.','', '- `01_run_four_poses.png`: 기본 보행1/7/15/25, 2×2.','- `02_firing_four_poses.png`: 이동사격2/12/26/32, 2×2.','- `03_idle_master.png`: 현재 대기0.','- `04_standing_fire_master.png`: 현재 정지사격85.','', '셀은 네이티브96×96, 원점48/48, 8배 최근접 확대다. 셀 밖 잘린 불투명 픽셀이 없음을 검사했다. 별도로 `moving_fire_inputs/`에는 네 폼별 대기/정지사격/이동사격 묶음/사용자 설정화 경로의 네 참고 입력을 준비했다. 원본 설정화는 수정하지 않았다.','', '새 그림은 기본형 보행과 이동사격의 얼굴·머리결·의상 구획을 대기와 같게 그리는 것이 우선이다. 현재 이동사격은 팔 스트립을 늘린 흔적이 있어 원화 색 몇 픽셀만 복원해서 해결할 수 없다. 기본2/26 소매 아래의 고립 검정점, 수영복 대시68/70/82/84의 팔 위 고립점과79 앞쪽 점도 새 상체 등록 때 조사해야 한다. 현재 readback의 BEFORE에도 보이는 기존 문제이고 이번 후보가 새로 만든 결함은 아니다.','', 'Ultimate217/218/220은 대시73을 재사용하여 만들었던 별도 노바 그림이다. 이번 후보는 이 특수14참조를 수정하지 않았다. 대시 수정 채택 후 노바 표시도 같은 머리 표현으로 이어져야 하므로 후속 통합 시 함께 다룬다.','', '위의 큰 색 덩어리·가는 사다리 외곽·팔 문제를 후보로만 무기한 남기는 것이 목적이 아니다. 새 아트 순서가 오면 준비된 큰 셀 입력으로 보행/이동사격부터 실제 재제작하고, 기존 단순 머리/소매를 다시 얹지 않은 전체 등록 결과를 대기와 재비교한다.']
 (OUT/'HANDOFF.md').write_text('\n'.join(lines)+'\n','utf8');print(json.dumps({'native_sheets_viewed':len(readback),'handoff':str((OUT/'HANDOFF.md').relative_to(ROOT))}))

if __name__=='__main__':main()
